if (structured.length > 0 && dbType) {
  let n = 0;
  for (const row of structured) {
    try {
      await gov.executeSQL(
        'INSERT INTO ' + tableName + ' (title, summary, content) VALUES (?, ?, ?)',
        [row.title || '', row.summary || '', row.content || '']
      );
      n++;
    } catch (e) {
      gov.log('写入失败: ' + e.message);
