  gov.log('入库完成: ' + tableName + ' 写入 ' + n + ' 条');
} else if (structured.length > 0) {
  gov.log('未关联数据库，仅展示结构化结果（关联数据库后可自动入库）');
  structured.slice(0, 5).forEach((r, i) => gov.log(`  [${i+1}] ${(r.title || '').slice(0, 30)}`));
}
gov.log('文档处理完成');

